def handler(body):
    lesson_id = body.get('lesson_id') if isinstance(body, dict) else None
    if not isinstance(lesson_id, str) or not lesson_id.strip():
        return 400, {'error': 'invalid_lesson_id'}
    return 200, {'ok': True, 'lesson_id': lesson_id.strip()}

assert handler({'lesson_id':' loops '})[0] == 200
assert handler({})[0] == 400
